 package approval

-import "time"
+import (
+	"crypto/hmac"
+	"crypto/sha256"
+	"encoding/base64"
+	"errors"
+	"fmt"
+	"strconv"
+	"strings"
+	"time"
+)

+const minSecretLen = 32
+
+// Sign creates a human-approval token binding taskID, actor, and an expiry
+// timestamp, authenticated with an HMAC-SHA256 MAC over the secret.
 func Sign(secret []byte, taskID, actor string, expires time.Time) (string, error) {
-	return "", nil
+	if len(secret) < minSecretLen {
+		return "", fmt.Errorf("approval: secret must be at least %d bytes", minSecretLen)
+	}
+	if taskID == "" {
+		return "", errors.New("approval: taskID must not be empty")
+	}
+	if actor == "" {
+		return "", errors.New("approval: actor must not be empty")
+	}
+
+	payload := encodePayload(taskID, actor, expires)
+	mac := computeMAC(secret, payload)
+
+	encodedPayload := base64.URLEncoding.EncodeToString([]byte(payload))
+	encodedMAC := base64.URLEncoding.EncodeToString(mac)
+
+	return encodedPayload + "." + encodedMAC, nil
 }

+// Verify validates a token against secret and taskID, returning the
+// authenticated actor if the token is well-formed, unmodified, bound to
+// taskID, and not expired relative to now.
 func Verify(secret []byte, token, taskID string, now time.Time) (string, error) {
-	return "", nil
+	if len(secret) < minSecretLen {
+		return "", fmt.Errorf("approval: secret must be at least %d bytes", minSecretLen)
+	}
+	if taskID == "" {
+		return "", errors.New("approval: taskID must not be empty")
+	}
+
+	parts := strings.SplitN(token, ".", 2)
+	if len(parts) != 2 {
+		return "", errors.New("approval: malformed token")
+	}
+
+	payloadBytes, err := base64.URLEncoding.DecodeString(parts[0])
+	if err != nil {
+		return "", fmt.Errorf("approval: malformed token payload: %w", err)
+	}
+	mac, err := base64.URLEncoding.DecodeString(parts[1])
+	if err != nil {
+		return "", fmt.Errorf("approval: malformed token mac: %w", err)
+	}
+
+	expectedMAC := computeMAC(secret, string(payloadBytes))
+	if !hmac.Equal(mac, expectedMAC) {
+		return "", errors.New("approval: token MAC mismatch")
+	}
+
+	fields := strings.SplitN(string(payloadBytes), "|", 3)
+	if len(fields) != 3 {
+		return "", errors.New("approval: malformed token fields")
+	}
+
+	tokenTaskID := fields[0]
+	actor := fields[1]
+	expiresUnix, err := strconv.ParseInt(fields[2], 10, 64)
+	if err != nil {
+		return "", fmt.Errorf("approval: malformed token expiry: %w", err)
+	}
+
+	if tokenTaskID != taskID {
+		return "", errors.New("approval: token is bound to a different task")
+	}
+
+	expires := time.Unix(expiresUnix, 0).UTC()
+	if now.UTC().After(expires) {
+		return "", errors.New("approval: token has expired")
+	}
+
+	return actor, nil
+}
+
+func encodePayload(taskID, actor string, expires time.Time) string {
+	return fmt.Sprintf("%s|%s|%d", taskID, actor, expires.UTC().Unix())
+}
+
+func computeMAC(secret []byte, payload string) []byte {
+	h := hmac.New(sha256.New, secret)
+	h.Write([]byte(payload))
+	return h.Sum(nil)
 }
